import{_ as r,a0 as l,w as d,s as p,ao as e,I as n,x as a,a1 as i,A as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const f=JSON.parse('{"title":"Linux 下使用iostat命令生成CPU和I/O的統計報告 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 下使用iostat命令生成CPU和I/O的統計報告 | LCTT (201402) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 下使用iostat命令生成CPU和I/O的統計報告 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 下使用iostat命令生成CPU和I/O的統計報告 | LCTT (201402) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201402/Linux iostat Command to Report CPU Statistics and IO Statistics","title":"Linux 下使用iostat命令生成CPU和I/O的統計報告","tag":"201402","desc":""},"relativePath":"201402/Linux iostat Command to Report CPU Statistics and IO Statistics.md","filePath":"[post].md"}'),h={name:"201402/Linux iostat Command to Report CPU Statistics and IO Statistics.md"};function m(g,t,u,c,x,b){const o=l("Link");return d(),p("div",null,[t[14]||(t[14]=e(`<h1 id="linux-下使用iostat命令生成cpu和i-o的統計報告" tabindex="-1">Linux 下使用iostat命令生成CPU和I/O的統計報告 <a class="header-anchor" href="#linux-下使用iostat命令生成cpu和i-o的統計報告" aria-label="Permalink to “Linux 下使用iostat命令生成CPU和I/O的統計報告”">​</a></h1><p>CPU是一台電腦的大腦。所有的處理命令都運行在上面。I/O（輸入/輸出）同樣扮演了一個重要角色。硬盤用於提供數據給處理器並保存CPU處理過的數據。一種衡量處理器和I/O利用率的方法是使用<strong>iostat</strong>命令。通過它們的利用率，我們可以決定是否該增加更多資源。</p><h2 id="iostat-是什麼" tabindex="-1">iostat 是什麼 <a class="header-anchor" href="#iostat-是什麼" aria-label="Permalink to “iostat 是什麼”">​</a></h2><p>iostat通過觀察設備的活躍時間和他們平均傳輸率之間的關係來監視系統的輸入/輸出設備負載。iostat生成的報告可以用於修改系統配置從而更好在物理硬盤間平衡輸入/輸出的報告。</p><h3 id="安裝-iostat" tabindex="-1">安裝 iostat <a class="header-anchor" href="#安裝-iostat" aria-label="Permalink to “安裝 iostat”">​</a></h3><p>iostat包含在<strong>sysstat</strong>包內。如果你沒有，你首先需要安裝它。</p><h4 id="在-redhat-centos-fedora" tabindex="-1">在 RedHat / CentOS / Fedora <a class="header-anchor" href="#在-redhat-centos-fedora" aria-label="Permalink to “在 RedHat / CentOS / Fedora”">​</a></h4><pre><code># yum install sysstat
</code></pre><h4 id="在-debian-ubuntu-linux-mint" tabindex="-1">在 Debian / Ubuntu / Linux Mint <a class="header-anchor" href="#在-debian-ubuntu-linux-mint" aria-label="Permalink to “在 Debian / Ubuntu / Linux Mint”">​</a></h4><pre><code>$ sudo apt-get install sysstat
</code></pre><h3 id="如何運行-iostat" tabindex="-1">如何運行 iostat <a class="header-anchor" href="#如何運行-iostat" aria-label="Permalink to “如何運行 iostat”">​</a></h3><p>要運行它，只需在控制台下<strong>輸入iostat</strong>。下面是一個例子。</p><pre><code>$ iostat
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2013/12/iostat_default.png" alt="iostat 默認報告"></p><h2 id="下面是如何讀取iostat默認報告" tabindex="-1">下面是如何讀取iostat默認報告 <a class="header-anchor" href="#下面是如何讀取iostat默認報告" aria-label="Permalink to “下面是如何讀取iostat默認報告”">​</a></h2><h3 id="第一部分包含了cpu報告" tabindex="-1">第一部分包含了CPU報告 <a class="header-anchor" href="#第一部分包含了cpu報告" aria-label="Permalink to “第一部分包含了CPU報告”">​</a></h3><ul><li><strong>%user</strong> : 顯示了在執行用户(應用)層時的CPU利用率</li><li><strong>%nice</strong> : 顯示了在以nice優先級運行用户層的CPU利用率</li><li><strong>%system</strong> : 顯示了在執行系統(內核)層時的CPU利用率</li><li><strong>%iowait</strong> : 顯示了CPU在I/O請求掛起時空閒時間的百分比</li><li><strong>%steal</strong> : 顯示了當hypervisor正服務於另外一個虛擬處理器時無意識地等待虛擬CPU所佔有的時間百分比。</li><li><strong>%idle</strong> : 顯示了CPU在I/O沒有掛起請求時空閒時間的百分比</li></ul><h3 id="第二部分包含了設備利用率報告" tabindex="-1">第二部分包含了設備利用率報告 <a class="header-anchor" href="#第二部分包含了設備利用率報告" aria-label="Permalink to “第二部分包含了設備利用率報告”">​</a></h3><ul><li><strong>Device</strong> : 列出的<strong>/dev</strong> 目錄下的設備/分區名稱</li><li><strong>tps</strong> : 顯示每秒傳輸給設備的數量。更高的tps意味着處理器更忙。</li><li><strong>Blk_read/s</strong> : 顯示了每秒從設備上讀取的塊的數量(KB,MB)</li><li><strong>Blk_wrtn/s</strong> : 顯示了每秒寫入設備上塊的數量(KB,MB)</li><li><strong>Blk_read</strong> : 顯示所有已讀取的塊</li><li><strong>Blk_wrtn</strong> : 顯示所有已寫入的塊</li></ul><h3 id="以kb或mb捕捉iostat" tabindex="-1">以KB或MB捕捉iostat <a class="header-anchor" href="#以kb或mb捕捉iostat" aria-label="Permalink to “以KB或MB捕捉iostat”">​</a></h3><p>默認上，iostat以B為單位衡量I/O系統。為了更便於閲讀，我們可以iostat將報告轉換成以KB或者MB為單位。只需要加入<strong>-k參數</strong>來創建以<strong>KB為單位</strong>，<strong>-m參數</strong>來創建以<strong>MB為單位</strong>。</p><pre><code>$ iostat -k
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2013/12/iostat_k.png" alt="以KB為單位的iostat"></p><pre><code>$ iostat -m
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2013/12/iostat_m.png" alt="以MB為單位的iostat"></p><p>要擴展報告，我們可以在iostat後面跟上<strong>-x選項</strong>。</p><pre><code>$ iostat -x
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2013/12/iostat_x.png" alt="擴展iostat報告"></p><h3 id="帶延遲使用iostat" tabindex="-1">帶延遲使用iostat <a class="header-anchor" href="#帶延遲使用iostat" aria-label="Permalink to “帶延遲使用iostat”">​</a></h3>`,29)),n("p",null,[t[1]||(t[1]=a("和",-1)),i(o,{href:"http://linoxide.com/linux-command/linux-vmstat-command-tool-report-virtual-memory-statistics/"},{default:s(()=>[...t[0]||(t[0]=[a("vmstat",-1)])]),_:1}),t[2]||(t[2]=a("一樣,作為一個統計工具，最好帶延遲參數來使用它。通過延遲參數，我們可以看到趨勢。這裏有一些帶延時運行iostat的示例。",-1))]),t[15]||(t[15]=e(`<h3 id="以kb為單位-2秒間隔-運行3次的方式運行iostat" tabindex="-1">以KB為單位，2秒間隔，運行3次的方式運行iostat <a class="header-anchor" href="#以kb為單位-2秒間隔-運行3次的方式運行iostat" aria-label="Permalink to “以KB為單位，2秒間隔，運行3次的方式運行iostat”">​</a></h3><pre><code>$ iostat -k 2 3
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2013/12/iostat_k_2_3.png" alt="iostat以KB來報告"></p><h3 id="只顯示cpu報告-並以3秒為間隔-報告6次" tabindex="-1">只顯示CPU報告，並以3秒為間隔，報告6次 <a class="header-anchor" href="#只顯示cpu報告-並以3秒為間隔-報告6次" aria-label="Permalink to “只顯示CPU報告，並以3秒為間隔，報告6次”">​</a></h3><pre><code>$ iostat -c 3 6
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2013/12/iostat_c_3_6.png" alt="以3秒為間隔，只顯示iostat"></p><h3 id="顯示hda2和hda6的設備報告-以2秒為間隔-報告4次" tabindex="-1">顯示hda2和hda6的設備報告，以2秒為間隔，報告4次 <a class="header-anchor" href="#顯示hda2和hda6的設備報告-以2秒為間隔-報告4次" aria-label="Permalink to “顯示hda2和hda6的設備報告，以2秒為間隔，報告4次”">​</a></h3><pre><code>$ iostat -d hda2 hda6 2 4
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2013/12/iostat_d_hda2_hda6_2_4.png" alt="只顯示硬盤的iostat"></p><h3 id="文件" tabindex="-1">文件 <a class="header-anchor" href="#文件" aria-label="Permalink to “文件”">​</a></h3><p>iostat使用這些文件來創建報告。</p><p><strong>/proc/stat</strong> 包含了系統統計 <strong>/proc/partitions</strong> 包含磁盤統計 (對於已打過補丁的2.5以前的內核) <strong>/proc/diskstats</strong> 包含磁盤統計 (對於2.5以後的內核) <strong>/sys</strong> 包含塊設備統計 (2.5以後內核)</p><h2 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h2><p>vmstat用於監視內存使用，iostat用於監視CPU使用率和I/O系統，這樣我們就有了完整的工具來監視你機器中三個重要的組件。這些工具的一個好處是你無需使用root權限運行它們。你可以瀏覽iostat的手冊來深入瞭解。只需在控制台下輸入<strong>man iostat</strong>就可進入iostat手冊界面。</p><hr>`,15)),n("p",null,[t[4]||(t[4]=a("via: ",-1)),i(o,{href:"http://linoxide.com/linux-command/linux-iostat-command/"},{default:s(()=>[...t[3]||(t[3]=[a("http://linoxide.com/linux-command/linux-iostat-command/",-1)])]),_:1})]),n("p",null,[t[7]||(t[7]=a("譯者：",-1)),i(o,{href:"https://github.com/geekpi"},{default:s(()=>[...t[5]||(t[5]=[a("geekpi",-1)])]),_:1}),t[8]||(t[8]=a(" 校對：",-1)),i(o,{href:"http://blog.csdn.net/tinyeyeser"},{default:s(()=>[...t[6]||(t[6]=[a("Mr小眼兒",-1)])]),_:1})]),n("p",null,[t[11]||(t[11]=a("本文由 ",-1)),i(o,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[9]||(t[9]=[a("LCTT",-1)])]),_:1}),t[12]||(t[12]=a(" 原創翻譯，",-1)),i(o,{href:"http://linux.cn/"},{default:s(()=>[...t[10]||(t[10]=[a("Linux中國",-1)])]),_:1}),t[13]||(t[13]=a(" 榮譽推出",-1))])])}const _=r(h,[["render",m]]);export{f as __pageData,_ as default};
